{"command":"cat << 'EOF' > /tmp/init_mes_db.sql
CREATE DATABASE mes_raw_data;
\c mes_raw_data

-- ==========================================
-- 1. 维度表 (Dimension Tables)：基础主数据
-- ==========================================

CREATE TABLE dim_work_order (
    wo_id VARCHAR(50) PRIMARY KEY,
    product_code VARCHAR(50),
    line_id VARCHAR(50),
    target_qty INT,
    completed_qty INT DEFAULT 0,
    status VARCHAR(20),
    plan_start_time TIMESTAMP,
    actual_start_time TIMESTAMP,
    close_time TIMESTAMP
);
COMMENT ON TABLE dim_work_order IS '工单维度表';
COMMENT ON COLUMN dim_work_order.wo_id IS '工单号(唯一)';
COMMENT ON COLUMN dim_work_order.target_qty IS '目标生产数量';
COMMENT ON COLUMN dim_work_order.completed_qty IS '已完工数量';

CREATE TABLE dim_equipment (
    eqp_id VARCHAR(50) PRIMARY KEY,
    eqp_name VARCHAR(100),
    line_id VARCHAR(50),
    station_type VARCHAR(50)
);
COMMENT ON TABLE dim_equipment IS '设备与产线维度表';
COMMENT ON COLUMN dim_equipment.station_type IS '工序类型(如 SMT, AOI, ICT, FCT, PACKING)';

-- ==========================================
-- 2. 事实表 (Fact Tables)：海量过站流水核心
-- ==========================================

CREATE TABLE fact_wip_log (
    log_id BIGSERIAL,
    sn VARCHAR(100) NOT NULL,
    wo_id VARCHAR(50),
    eqp_id VARCHAR(50),
    process_name VARCHAR(50),
    is_pass BOOLEAN,
    is_rework BOOLEAN,
    operator VARCHAR(50),
    created_at TIMESTAMP NOT NULL,
    PRIMARY KEY (created_at, log_id)
) PARTITION BY RANGE (created_at);
COMMENT ON TABLE fact_wip_log IS 'MES海量过站记录(SN级别追踪表)';
COMMENT ON COLUMN fact_wip_log.is_pass IS '测试/过站是否良品 (TRUE=Pass, FALSE=Fail)';
COMMENT ON COLUMN fact_wip_log.is_rework IS '是否属于返修后再投入 (用于排查伪直通率)';
COMMENT ON COLUMN fact_wip_log.created_at IS '数据生成时间(分区键)';

CREATE INDEX idx_wip_wo_id ON fact_wip_log(wo_id);
CREATE INDEX idx_wip_sn ON fact_wip_log(sn);
CREATE INDEX idx_wip_eqp ON fact_wip_log(eqp_id);

-- 写一段基础的 PL/pgSQL 用于快速生成未来30天的分区表
DO $$
DECLARE
    curr_date DATE := CURRENT_DATE - INTERVAL '5 days';
    end_date DATE := CURRENT_DATE + INTERVAL '30 days';
    part_name TEXT;
    start_bound TEXT;
    end_bound TEXT;
BEGIN
    WHILE curr_date <= end_date LOOP
        part_name := 'fact_wip_log_y' || TO_CHAR(curr_date, 'YYYY') || 'm' || TO_CHAR(curr_date, 'MM') || 'd' || TO_CHAR(curr_date, 'DD');
        start_bound := TO_CHAR(curr_date, 'YYYY-MM-DD');
        end_bound := TO_CHAR(curr_date + 1, 'YYYY-MM-DD');
        EXECUTE 'CREATE TABLE IF NOT EXISTS ' || part_name || ' PARTITION OF fact_wip_log FOR VALUES FROM (''' || start_bound || ''') TO (''' || end_bound || ''');';
        curr_date := curr_date + 1;
    END LOOP;
END $$;

-- ==========================================
-- 3. 汇总表 (Aggregate Tables)：为 AI 秒级查询准备
-- ==========================================

CREATE TABLE agg_daily_yield (
    work_date DATE,
    line_id VARCHAR(50),
    process_name VARCHAR(50),
    total_in INT,
    total_pass INT,
    first_pass INT,
    fpy_rate DECIMAL(5,4),
    yield_rate DECIMAL(5,4),
    PRIMARY KEY (work_date, line_id, process_name)
);
COMMENT ON TABLE agg_daily_yield IS '每日产线良率与直通率物理汇总宽表(AI快速输出首选)';
COMMENT ON COLUMN agg_daily_yield.fpy_rate IS '直通率(首次测试即过关的比例)，格式为小数0.9922=99.22%';
COMMENT ON COLUMN agg_daily_yield.yield_rate IS '最终良率(包含返修后通过的比例)';

EOF

ssh -o BatchMode=yes 10.139.1.5 'sudo -u postgres psql -f /tmp/init_mes_db.sql'
"}

