CREATE DATABASE hikvision_attendance;
\c hikvision_attendance

-- ==========================================
-- 1. 维度表 (Dimension Tables)
-- ==========================================

CREATE TABLE dim_employee (
    emp_id VARCHAR(50) PRIMARY KEY,
    emp_name VARCHAR(100) NOT NULL,
    department VARCHAR(100),
    position VARCHAR(100),
    job_status VARCHAR(20) DEFAULT 'ACTIVE' -- ACTIVE, RESIGNED
);
COMMENT ON TABLE dim_employee IS '员工基础信息维度表';
COMMENT ON COLUMN dim_employee.emp_id IS '工号 (极其关键的全司唯一标识)';
COMMENT ON COLUMN dim_employee.job_status IS '在职状态';

CREATE TABLE dim_device (
    device_id VARCHAR(50) PRIMARY KEY,
    device_name VARCHAR(100),
    location VARCHAR(100),
    ip_address VARCHAR(50),
    device_type VARCHAR(50) -- FACE, FINGERPRINT, CARD
);
COMMENT ON TABLE dim_device IS '海康考勤机/门禁设备维度表';

-- ==========================================
-- 2. 核心事实表 (Fact Table): 原始打卡流水
-- ==========================================

CREATE TABLE fact_swipe_log (
    log_id BIGSERIAL PRIMARY KEY,
    emp_id VARCHAR(50) NOT NULL,
    device_id VARCHAR(50),
    swipe_time TIMESTAMP NOT NULL,
    direction VARCHAR(20),     -- IN, OUT, UNKNOWN
    auth_type VARCHAR(20),     -- FACE(人脸), CARD(刷卡)
    temperature DECIMAL(4,1)   -- 测温(若设备支持，备用保留)
);
COMMENT ON TABLE fact_swipe_log IS '海康员工打卡/刷脸原始流水';
COMMENT ON COLUMN fact_swipe_log.direction IS '进出方向：往往是从海康门禁通道方向获取';
COMMENT ON COLUMN fact_swipe_log.auth_type IS '认证类型：如人脸(FACE)';

-- 因为考勤流水虽然不如MES大，但长年累月也很可观，建立高频查询索引
CREATE INDEX idx_swipe_emp_time ON fact_swipe_log(emp_id, swipe_time);
CREATE INDEX idx_swipe_time ON fact_swipe_log(swipe_time);

-- ==========================================
-- 3. 专属聚合表 (Aggregation Table): 供AI直接查询个人每日考勤结果
-- ==========================================

CREATE TABLE agg_daily_attendance (
    emp_id VARCHAR(50),
    work_date DATE,
    first_in TIMESTAMP,
    last_out TIMESTAMP,
    work_hours DECIMAL(5,2),
    attendance_status VARCHAR(20), -- NORMAL(正常), LATE(迟到), EARLY_LEAVE(早退), ABSENT(缺勤)
    shift_name VARCHAR(50),
    PRIMARY KEY (emp_id, work_date)
);
COMMENT ON TABLE agg_daily_attendance IS '每日考勤核算结果表(AI回答员工考勤的首选表)';
COMMENT ON COLUMN agg_daily_attendance.first_in IS '当日首次打卡(上班)时间';
COMMENT ON COLUMN agg_daily_attendance.last_out IS '当日末次打卡(下班)时间';
COMMENT ON COLUMN agg_daily_attendance.work_hours IS '在厂工作时长(小时)';
COMMENT ON COLUMN agg_daily_attendance.attendance_status IS '考勤状态判定结果';

SQL

sudo -u postgres psql -f /tmp/init_attendance_db.sql
EOF"}

